In data-driven and simulation-based disciplines, the optimization problem
\begin{equation} \label{problem}
\min_{\theta} F(\theta)
\end{equation}

is frequently solved, 
where $F(\theta) = \E{ f(\theta,X)}$; $f: \mathbb{R}^p \times \mathbb{R}^d \to \mathbb{R}$; $X$ is a random variable with arbitrary support; and $\mathbb{E}$ is the expectation operator. Depending on $X$, the optimization problem's objective function and its gradient may be impractical or impossible to evaluate directly \cite{bertsekas2011}. Fortunately, when certain regularity conditions hold on $f$ and $X$ (e.g., \cite{bottou2018,wu2009}), the optimization problem's structure is exploited to generate solvers that use the gradient of $f$ with respect to the argument $\theta$ for independent copies of $X$ \cite{robbins1951,chung1954}. Moreover, when the gradient of $f$ is significantly cheaper to compute than the gradient of $F$, the optimization problem can be efficiently solved using these so-called Stochastic Gradient Descent (SGD) methods \cite{bertsekas2011}.


\nomenclature[A, 1]{$F$}{Objective function that maps $\mathbb{R}^p \to \mathbb{R}$. Also referred to as ``Deterministic Objective.''}
\nomenclature[A, 2]{$\dot F$}{Gradient function of the deterministic objective that maps $\mathbb{R}^p \to \mathbb{R}^p$. Also referred to as ``Deterministic Gradient.''}
\nomenclature[A, 3]{$f$}{A function that maps $\mathbb{R}^p \times \mathbb{R}^d \to \mathbb{R}$. Used to construct the deterministic objective, and is referred to as the ``Stochastic Objective.''}
\nomenclature[A, 4]{$\dot f$}{Gradient function of the stochastic objective with respect to the first argument, and maps $\mathbb{R}^p \times \mathbb{R}^d \to \mathbb{R}^p$. Also referred to as the ``Stochastic Gradient.''}
\nomenclature[A, 5]{$\theta$}{The parameter to be optimized in the objective function. Takes value in $\mathbb{R}^p$.}
\nomenclature[A, 6]{$\norm{\cdot}_2$}{If the argument is a vector, this refers to the Euclidean norm of the vector. If the argument is a matrix, this refers to the Operator 2-norm.}
\nomenclature[A, 7]{$\lambda_{\max}$}{The largest eigenvalue corresponding to a given symmetric, positive definite matrix argument.}
\nomenclature[A, 8]{$\lambda_{\min}$}{The smallest eigenvalue corresponding to the given symmetric, positive definite matrix argument.}
\nomenclature[A, 9]{$\kappa $}{The 2-norm condition number of the given matrix.}


\nomenclature[B, 1]{$\mathbb{P}$}{The probability operator with respect to the underlying Probability Space.}
\nomenclature[B, 2]{$\mathbb{E}$}{The expectation operator corresponding to the underlying Probability Space.}
\nomenclature[B, 3]{$X, X_k$}{Independent, identically distributed random variables that map from the underlying Probability Space to $\mathbb{R}^d$.}


\nomenclature[B, 7]{$i.o.$}{Infinitely often.}
\nomenclature[B, 8]{$\mathbf{1}$}{The indicator function over a specified event.}


\condition{condition-noise-grad}{There exists a $C_1,C_2 \geq 0$ such that, $\forall \theta \geq 0$,
$$ \E{ \norm{ \dot{f}(\theta,X) - \dot{F}(\theta)}_2^2} \leq C_1 + C_2 \norm{ \dot{F}(\theta)}_2^2.$$}{NM-4}


\condition{condition-dg-lipschitz}{There exista a $C > 0$ such that for all $\theta_1,\theta_2$, 
$$ \norm{ \dot{F}(\theta_1) - \dot{F}(\theta_2)}_2 \leq C \norm{\theta_1 - \theta_2}_2.$$}{DG-2}


\condition{bcn}{The BCN conditions are

\begin{enumerate}
\item $F$ is bounded from below.
\item $\dot{F}$ is Lipschitz continuous (\ref{condition-dg-lipschitz}).
\item For all $\theta \in \mathbb{R}^p$, $\dot{F}(\theta) = \mathbb{E}[ \dot{f}(\theta,X)]$.
\item The stochastic gradients satisfy \ref{condition-noise-grad}.
\end{enumerate}}{BCN}


\begin{definition}
A function that satisfies the BCN conditions is referred to as a BCN function.
\end{definition}

Let $\lbrace X_k : k \in \mathbb{N} \rbrace$ be independent and identically distributed random variables that have the same distribution as $X$. Let $\beta_0$ be either a fixed or random quantity in $\mathbb{R}^p$. Let $\mathcal{F}_0 = \sigma(\beta_0)$ and $\mathcal{F}_k = \sigma(\beta_0, X_1,\ldots,X_k)$ denote the corresponding elements of the usual filtration. Define the Stochastic Gradient Descent iterates $\lbrace \beta_k : k \in \mathbb{N} \rbrace$ recursively by
\begin{equation}
\beta_{k+1} = \beta_k - M_k \dot f (\beta_k, X_{k+1}),
\end{equation} 
where $\lbrace M_k \rbrace$ are matrices that satisfy:
\condition{prop-sympd}{The matrices $\lbrace M_k \rbrace$ are symmetric and positive definite.}{P1}
\condition{prop-maxeig}{There exists an $S > 0$ such that
$$\sum_{k=0}^\infty \lambda_{\max}(M_k)^2 < S,$$
where $\lambda_{\max}(\cdot)$ denotes the largest eigenvalue of the given matrix.}{P2}
\condition{prop-mineig}{The sum,
$$\sum_{k=0}^\infty \lambda_{\min}(M_k),$$
diverges, where $\lambda_{\min}(\cdot)$ is the smallest eigenvalue of the given matrix.}{P3}
\condition{prop-condnum}{The condition numbers of $\lbrace M_k \rbrace$ with respect to operator 2-norm, $\lbrace \kappa(M_k) \rbrace$, satisfy
$$ \lim_{k \to \infty} \lambda_{\max}(M_k) \kappa(M_k) = 0.$$
}{P4}


\begin{remark}
We also note that all of the inequalities and equalities below hold with probability one, even if this is not explicitly stated.
\end{remark}
\begin{remark}
We also point out that the probabilities and expectations below should be conditional on $\mathcal{F}_0$. However, to avoid the additional cumbersome notation, we will not explicitly state this.
\end{remark}


Our first task will be to set the stage to the analogue of strong Markov property that will be relevant in analyzing the SGD method. Let $\tau$ be a finite stopping time with respect to $\lbrace \mathcal{F}_k \rbrace$; that is, $\Prb{ \tau < \infty} = 1$. Moreover, as all of our arguments will be asymptotic in this section, we will assume also that $\Prb{ \tau \geq K} = 1$ where $K \in \mathbb{N}$ is defined in the following lemma to satisfy the following property, which will be used later. 


Now, using $\tau$, we will define a sequence of iterates $\lbrace \psi_k \rbrace$ that we will eventually couple with $\lbrace \beta_k \rbrace$. To define $\lbrace \psi_k \rbrace$, let
\begin{enumerate}
\item $Z_k := X_{\tau+1+k}$ for all $k \in \mathbb{N}$.
\item $\psi_0 := \beta_{\tau + 1}$.
\item For all $k \in \lbrace 0 \rbrace \cup \mathbb{N}$, $P_k := M_{\tau+1+k}$ and
\begin{equation} \label{eqn-psi-iter}
\psi_{k+1} := \psi_k - P_k \dot f( \psi_k, Z_{k+1}) \1{ \norm{\dot F(\psi_k)}_2^2 > \delta},
\end{equation}
where $\1{ \cdot} $ is the indicator function for the given event.
\end{enumerate} 

There are two properties of these quantities that are worth noting: $\lbrace Z_k \rbrace$ are independent and identically distributed; $\lbrace P_k \rbrace$ inherit the properties of $\lbrace M_k \rbrace$ with probability one. The former is verified by Theorem 4.1.3 of \cite{durrett2010}, which states that $\lbrace Z_k \rbrace$ are mutually independent and independent of $\mathcal{F}_{\tau+1}$, and have the same distribution as $X_1$. The latter is verified by the following lemma.

