\begin{lemma} \label{lemma-minimality-smallest-eigenvalue}
Suppose $\lbrace M_k \rbrace$ satisfy \ref{prop-sympd} to \ref{prop-condnum}, and recall that $C$ is the Lipschitz constant in \ref{condition-dg-lipschitz} and $C_2$ is the scaling constant in \ref{condition-noise-grad}. There exists a $K \in \mathbb{N}$ such that, for all $k \geq K$ and for any eigenvalue, $\lambda$ of $M_k$,
\begin{equation} \label{eqn-grad-norm-lb}
\frac{1}{2} \lambda_{\min}(M_k) \leq \lambda - \frac{C}{2}\lambda^2 - \frac{C C_2}{2} \lambda_{\max}(M_k)^2.
\end{equation}
\end{lemma}

\begin{proof}
We begin by showing that right hand side of \eqref{eqn-grad-norm-lb} is minimized when $\lambda = \lambda_{\min}(M_k)$ for all $k$ sufficiently large and then establish \eqref{eqn-grad-norm-lb} for this choice of $\lambda$. 
We first establish
\begin{equation} \label{eqn-def-K}
\lambda_{\max}(M_k) + \lambda_{\min}(M_k) \leq \frac{2}{C}.
\end{equation}
By \ref{prop-maxeig}, $\lambda_{\max}(M_k) \to 0$. Therefore, there exists a $k_0 \in \mathbb{N}$ such that for all $k \geq k_0$, $\lambda_{\max}(M_k) \leq 1/C$. Therefore, (\ref{eqn-def-K}) follows for all $k \geq k_0$. Moreover, for every $k \geq k_0$, we see that (\ref{eqn-def-K}) holds for any other eigenvalue of $M_k$ in place of $\lambda_{\max}(M_k)$. Letting $\lambda$ denote any eigenvalue of $M_k$ and noting that $\lambda - \lambda_{\min}(M_k) \geq 0$,
\begin{equation}
(\lambda - \lambda_{\min}(M_k) ) (\lambda + \lambda_{\min}(M_k) ) \leq \frac{2}{C}(\lambda - \lambda_{\min}(M_k) ),
\end{equation}
which can be rearranged to conclude that, for any $k \geq k_0$ and for any eigenvalue $\lambda$ of $M_k$,
\begin{equation}
\begin{aligned}
\lambda_{\min}(M_k) - \frac{C}{2}\lambda_{\min}(M_k)^2 \leq \lambda - \frac{C}{2}\lambda^2.
\end{aligned}
\end{equation} 
It follows that the right hand side of \eqref{eqn-grad-norm-lb} is minimized by $\lambda_{\min}(M_k)$.

We now establish \eqref{eqn-grad-norm-lb} with $\lambda = \lambda_{\min}(M_k)$ by contradiction. Suppose that there exists a subsequence $\lbrace k_j \rbrace$ for which \eqref{eqn-grad-norm-lb} does not hold; that is, by rearranging \eqref{eqn-grad-norm-lb},
\begin{equation}
C \lambda_{\min}(M_{k_j})^2 + CC_2 \lambda_{\max}(M_{k_j})^2 > \lambda_{\min}(M_{k_j}).
\end{equation}
Taking an upper bound on the left hand side,
\begin{align}
2C(C_2 + 1) \lambda_{\max}(M_{k_j})^2 > \lambda_{\min}(M_{k_j}).
\end{align}
Hence,
\begin{equation} \label{eqn-relaxed-condnum-control}
\lambda_{\max}(M_{k_j}) \kappa( M_{k_j} ) > \frac{1}{2 C(C_2 + 1)},
\end{equation}
which contradicts \ref{prop-condnum} for $j$ sufficiently large. Hence, there is a $K \geq k_0$ such that, for all $k \geq K$, \eqref{eqn-grad-norm-lb} holds.
\qed
\end{proof}

\begin{lemma} \label{lemma-pk-satisfy-mk-properties}
With probability one, $\lbrace P_k \rbrace$ satisfy \ref{prop-sympd} to \ref{prop-condnum}. Moreover, with probability one, for all $k \geq 0$ and any eigenvalue $\lambda$ of $P_k$,
\begin{equation}
\frac{1}{2}\lambda_{\min}(P_k) \leq \lambda - \frac{C}{2} \lambda^2 - \frac{C C_2}{2} \lambda_{\max}(P_k)^2.
\end{equation}
\end{lemma}

\begin{proof}
The result follows from a standard divide and conquer argument. For \ref{prop-sympd},
\begin{align}
&\Prb{ P_k = P_k', P_k \succ 0 } = \Prb{ M_{\tau+1+k}' = M_{\tau+1+k}, M_{\tau+1+k} \succ 0} \\
&= \sum_{j=0}^\infty \condPrb{ M_{j + 1 +k}' = M_{j + 1 +k}, M_{j+1+k} \succ 0}{\tau = j} \Prb{ \tau = j} \\
&= \sum_{j=0}^\infty \underbrace{\Prb{ M_{j + 1 +k}' = M_{j + 1 +k}, M_{j+1+k} \succ 0 }}_{=1~\text{by \ref{prop-sympd} on } \lbrace M_k \rbrace } \Prb{ \tau=j} \\
&= \sum_{j=0}^\infty \Prb{ \tau = j} \\
&= \Prb{ \tau < \infty } = 1.
\end{align}
Similarly, for \ref{prop-maxeig},
\begin{align}
&\Prb{ \sum_{k=0}^\infty \lambda_{\max}(P_k)^2 < S} \\
&= \sum_{j=0}^\infty \underbrace{\condPrb{ \sum_{k=0}^\infty \lambda_{\max}(M_{j+1+k})^2 < S}{\tau=j}}_{=1~\text{by \ref{prop-maxeig} on } \lbrace M_k \rbrace} \Prb{ \tau=j} \\
&= \Prb{ \tau < \infty} =1.
\end{align}
The analogous arguments will show that the remaining conclusions of the lemma hold.
\qed
\end{proof}

From these properties, we see that if (\ref{eqn-psi-iter}) did not have the indicator term, then the only difference between $\lbrace \psi_k \rbrace$ and $\lbrace \beta_k \rbrace$ is the initialization---the fact that $\lbrace P_k \rbrace$ and $\lbrace M_k \rbrace$ are distinct is of little importance for our purposes as long as \ref{prop-sympd} to \ref{prop-condnum} are satisfied. Thus, we see that $\lbrace \beta_k \rbrace$ exhibit an analogue of the strong Markov property.

Now, to couple these two iterate sequences, let $\mathcal{G}_0 = \mathcal{F}_{\tau+1}$ and $\mathcal{G}_k = \sigma(\mathcal{F}_{\tau+1},Z_1,\ldots,Z_k)$, and, for $\delta >0$, define $\tau_\delta$ to be a stopping time with respect to $\lbrace \mathcal{G}_k \rbrace$ such that
\begin{equation}
\tau_\delta = \min\left\lbrace k \geq 0: \norm{ \dot{F}(\psi_k)}_2^2 \leq \delta \right\rbrace.
\end{equation} 
Then, on the event $\lbrace k \geq \tau_\delta \rbrace$, $\psi_{k+1} = \psi_k$. Moreover, on the event $\lbrace k < \tau_\delta \rbrace$,
\begin{equation}
\begin{aligned}
\psi_{k+1} &= \psi_{k} - P_k \dot{f}( \psi_k, Z_{k+1}) \\
&= \beta_{\tau+1+k} - M_{\tau+1 + k} \dot{f}( \beta_{\tau+1+k}, X_{\tau+2+k}) = \beta_{\tau+2+k}
\end{aligned}
\end{equation}
follows by induction. Therefore, for all $0 \leq k \leq \tau_\delta$, $\psi_k = \beta_{\tau+1+k}$; that is, the sequences are coupled in this interval. Owing to this coupling, we see that $\tau_\delta + 1$ is the number of iterates for $\beta_k$ to be within a ``$\delta$-region of zero gradient'' after iterate $\tau$. We now apply Zoutendijk's global convergence approach to conclude that $\tau_\delta$ is finite with probability one.

We now apply Zoutendijk's global convergence approach \cite{zoutendijk1970} to $\lbrace \psi_k \rbrace$ to conclude that $\Prb{ \tau_\delta < \infty} = 1$. First, by the fundamental theorem of calculus and \ref{condition-dg-lipschitz} (recall, with constant $C$),
\begin{align}
F(\psi_{k+1}) &\leq F(\psi_k) + \dot{F}(\psi_k)'(\psi_{k+1} - \psi_k) + \frac{C}{2}\norm{ \psi_{k+1} - \psi_k}_2^2 \\
			  & \begin{aligned}
			  &=F(\psi_k) - \dot{F}(\psi_k)'P_k \dot f (\psi_k, Z_{k+1}) \1{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta} \\
			  &+ \frac{C}{2} \norm{ P_k \dot f(\psi_k, Z_{k+1})}_2^2 \1{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta}. 
			  \end{aligned} \label{eqn-ftc}
\end{align}
We now take the conditional expectation of the resulting inequality with respect to $\mathcal{G}_k$. Note, since $\psi_k, P_k$ are measurable with respect to $ \mathcal{G}_k$ and $Z_{k+1}$ is independent of $\mathcal{G}_k$, then $\cond{ F(\psi_k)}{\mathcal G_k} = F(\psi_k)$ and 
\begin{equation}
\cond{ \dot{F}(\psi_k)'P_k \dot f(\psi_k, Z_{k+1})}{\mathcal{G}_k} = \dot{F}(\psi_k)'P_k \dot{F}(\psi_k).
\end{equation}
For the third term in (\ref{eqn-ftc}), we will need to make use of \ref{condition-noise-grad} (with parameters $C_1,C_2 \geq 0$).
\begin{align}
&\cond{ \norm{ P_k \left[ \dot f(\psi_k, Z_{k+1}) - \dot{F}(\psi_k) + \dot{F}(\psi_k) \right]}_2^2}{\mathcal G_k} \nonumber \\
&= \cond{ \norm{P_k \left[ \dot f(\psi_k,Z_{k+1}) - \dot{F}(\psi_k) \right]}_2^2}{\mathcal{G}_k} + \dot F(\psi_k)'P_k^2 \dot F(\psi_k) \\
&\leq C_1\lambda_{\max}(P_k)^2 + C_2 \lambda_{\max}(P_k)^2 \norm{ \dot{F}(\psi_k)}_2^2 + \dot F(\psi_k)'P_k^2 \dot F(\psi_k)
\end{align}
Putting the calculation for these three terms together in (\ref{eqn-ftc}), we conclude
\begin{equation} \label{eqn-ftc-cond}
\begin{aligned}
&\cond{F(\psi_{k+1})}{\mathcal{G}_k} \leq F(\psi_k) + \frac{CC_1}{2} \lambda_{\max}(P_k)^2 -  \1{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta} \\
&\times \left[\dot{F}(\psi_k)'P_k \dot F(\psi_k) - \frac{C}{2} \dot{F}(\psi_k)'P_k^2 \dot F(\psi_k) - \frac{C C_2}{2} \lambda_{\max}(P_k)^2 \norm{ \dot F(\psi_k)}_2^2 \right]. 
\end{aligned}
\end{equation}
We can find an upper bound for (\ref{eqn-ftc-cond}) by finding a lower bound for the third term in the right hand side of the inequality. In particular, we will lower bound
\begin{equation} \label{eqn-ftc-cond-min}
\min_{v \in \mathbb{S}^{p-1}} v'P_k v - \frac{C}{2} v' P_k^2 v - \frac{C C_2}{2} \lambda_{\max}(P_k)^2 \norm{v}_2^2,
\end{equation}
where $\mathbb S^{p-1}$ is the unit sphere in $\mathbb {R}^p$.\footnote{We could drop the last term in the optimization problem as it is a constant.}

Using the Schur decomposition of $P_k$,\footnote{Since $P_k$ is random, its Schur decomposition is random.} we can transform (\ref{eqn-ftc-cond-min}) into the equivalent problem
\begin{equation} \label{eqn-ftc-cond-min-2}
\min_{v \in \mathbb{S}^{p-1}} \sum_{i=1}^p \left[\lambda_i  - \frac{C}{2} \lambda_i^2 - \frac{C C_2}{2} \lambda_1^2\right] v_i^2,
\end{equation}
where $\lambda_{\max}(P_k) = \lambda_1 \geq \lambda_2 \geq \cdots \geq \lambda_p = \lambda_{\min}(P_k)$; and $v_i$ are the components of $v$. Applying Lemma \ref{lemma-pk-satisfy-mk-properties}, the solution to (\ref{eqn-ftc-cond-min-2}) is lower bounded by $\lambda_{\min}(P_k)/2$.


Plugging this lower bound into (\ref{eqn-ftc-cond}), we have that
\begin{equation}
\begin{aligned}
\cond{F(\psi_{k+1})}{\mathcal{G}_k} &\leq F(\psi_k) + \frac{CC_1}{2} \lambda_{\max}(P_k)^2 \\
&\quad - \frac{1}{2}\lambda_{\min}(P_k)\norm{ \dot{F} (\psi_k)}_2^2 \1{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta}.
\end{aligned}
\end{equation}
Rearranging and applying the condition in the indicator,
\begin{equation}
\begin{aligned}
&\frac{\delta}{2}\lambda_{\min}(P_k) \1{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta} \\
&\quad \leq F(\psi_k) - \cond{ F(\psi_{k+1})}{ \mathcal{G}_k} + \frac{C C_1}{2} \lambda_{\max}(P_k)^2.
\end{aligned}
\end{equation}
Now, recall that $P_k$ are measurable with respect to $\mathcal{F}_{\tau+1}$ and recall that $\mathcal{F}_{\tau+1} \subset \mathcal{G}_k$ for all $k$. Therefore,
\begin{equation}
\begin{aligned}
&\frac{\delta}{2}\lambda_{\min}(P_k) \condPrb{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta }{ \mathcal{F}_{\tau+1}} \\
&\quad \leq \cond{ F(\psi_k) - F(\psi_{k+1})}{\mathcal{F}_{\tau+1}} + \frac{C C_1}{2} \lambda_{\max}(P_k)^2.
\end{aligned}
\end{equation}
Moreover, by (a) summing both sides from $k=0$ to $n \in \mathbb{N}$, (b) recalling that $F(\psi_0)$ is finite with probability one given $\mathcal{F}_{\tau+1}$, and (c) applying \ref{prop-maxeig} from Lemma \ref{lemma-pk-satisfy-mk-properties}, we conclude
\begin{equation}
\begin{aligned}
&\frac{\delta}{2} \sum_{k=0}^n \lambda_{\min}(P_k) \condPrb{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta }{ \mathcal{F}_{\tau+1}} \\
&\quad \leq F(\psi_0) - \cond{ F(\psi_{n+1})}{\mathcal{F}_{\tau+1}} + \frac{SCC_1}{2}.
\end{aligned}
\end{equation}

Recall that, we have assumed that $F(\theta)$ is bounded from below by some constant $F_{l.b.}$ as a core assumption. Using this, we see that
\begin{equation}
\begin{aligned}
\frac{\delta}{2} \sum_{k=0}^n \lambda_{\min}(P_k) \condPrb{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta }{ \mathcal{F}_{\tau+1}} 
\leq F(\psi_0) - F_{l.b.} + \frac{SCC_1}{2}.
\end{aligned}
\end{equation}

Moreover, note that, for all $k \geq 0$,
\begin{equation}
\condPrb{ \bigcap_{j=0}^\infty \left\lbrace \norm{ \dot{F}(\psi_j)}_2^2 > \delta \right\rbrace }{ \mathcal{F}_{\tau+1}} \leq \condPrb{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta }{ \mathcal{F}_{\tau+1}}. 
\end{equation}
Therefore, for arbitrary $n$,
\begin{equation}
\condPrb{ \bigcap_{j=0}^\infty \left\lbrace \norm{ \dot{F}(\psi_j)}_2^2 > \delta \right\rbrace }{ \mathcal{F}_{\tau+1}} \leq \frac{F(\psi_0) - F_{l.b.} + S C C_1 /2 }{(\delta/2)\sum_{k=0}^n \lambda_{\min}(P_k)}
\end{equation} 
By \ref{prop-mineig} from Lemma \ref{lemma-pk-satisfy-mk-properties}, the right hand side of this inequality can be made arbitrarily small, which implies that the conditional probability on the left hand side is zero.

That is,
\begin{equation}
0 = \condPrb{ \bigcap_{j=0}^\infty  \left\lbrace \norm{ \dot{F}(\psi_j)}_2^2 > \delta \right\rbrace }{ \mathcal{F}_{\tau+1}} = \condPrb{ \tau_{\delta} = \infty}{\mathcal{F}_{\tau+1}}.
\end{equation}
