\begin{equation} \label{eqn-set-inc-2}
\begin{aligned}
&\left\lbrace \norm{\dot{F}(\beta_k)}_2 \leq \delta,~ \norm{\dot{F}(\beta_{k+1})}_2 > \delta, ~i.o. \right\rbrace \\
&\quad = 
\left\lbrace \norm{ \dot{F}(\beta_{k+1})}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} > \delta, ~i.o. \right\rbrace.
\end{aligned}
\end{equation}

We will now show that this ultimate event occurs with probability zero using Markov's inequality and the Borel-Cantelli lemma. Let $\epsilon > 0$ and recall that $C > 0$ is the parameter in \ref{condition-dg-lipschitz}. Then,
\begin{align}
&\condPrb{ \norm{ \dot{F}(\beta_{k+1})}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} \geq \delta + C \epsilon }{\mathcal{F}_k} \\
&\begin{aligned}
&\leq \mathbb{P}\bigg{[} \left( \norm{ \dot{F}(\beta_{k+1}) - \dot{F}(\beta_k) }_2 + \norm{ \dot{F}(\beta_k)}_2 \right) \1{ \norm{\dot{F}(\beta_k)}_2\leq \delta}  \\
&\quad  \geq \delta + C \epsilon \bigg{\vert} \mathcal{F}_k \bigg{]}
\end{aligned} \\
&\leq \condPrb{ \norm{ \dot{F}(\beta_{k+1}) - \dot{F}(\beta_k)}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} + \delta \geq \delta + C \epsilon}{\mathcal{F}_k}\\
& \leq \condPrb{ C \norm{\beta_{k+1} - \beta_k}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} \geq  C \epsilon}{\mathcal{F}_k} \\
& \leq \condPrb{ \norm{M_k \dot{f}(\beta_k, X_{k+1})}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} \geq   \epsilon}{\mathcal{F}_k}
\end{align}

Applying Markov's inequality to the last conditional probability and using \ref{condition-noise-grad},
\begin{align}
&\condPrb{ \norm{ \dot{F}(\beta_{k+1})}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} \geq \delta + C \epsilon }{\mathcal{F}_k} \\
& \leq \frac{\lambda_{\max}(M_k)^2}{\epsilon^2}\left[ C_1 + (C_2+1) \norm{ \dot{F}(\beta_k)}_2^2 \right] \1{ \norm{ \dot{F}(\beta_k)}_2 \leq \delta}  \\
& \leq \frac{\lambda_{\max}(M_k)^2}{\epsilon^2}\left[ C_1 + (C_2+1)\delta^2 \right]
\end{align}

By \ref{prop-maxeig}, the sum of the right hand side is bounded with probability one. Therefore, by the conditional second Borel-Cantelli lemma (Theorem 5.3.2 of \cite{durrett2010}),
\begin{equation}
\Prb{\norm{ \dot{F}(\beta_{k+1})}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} \geq \delta + C \epsilon, ~i.o.} = 0. 
\end{equation}

\begin{theorem} \label{theorem-revisit}
Let $F$ be a Bottou-Curtis-Nocedal function (\ref{bcn}) and let $\lbrace \beta_k \rbrace$ be the iterates generated by Stochastic Gradient Descent satisfying \ref{prop-sympd} to \ref{prop-condnum} (\S \ref{subsection-sgd}), then, for any $\delta > 0$,
\begin{equation}
\condPrb{ \norm{ \dot F( \beta_k)}_2^2 \leq \delta, ~i.o.}{\mathcal{F}_0} = 1 ~\text{with probability 1},
\end{equation}
where $\mathcal{F}_0 = \sigma(\beta_0)$.
\end{theorem}

From these properties, we see that if (\ref{eqn-psi-iter}) did not have the indicator term, then the only difference between $\lbrace \psi_k \rbrace$ and $\lbrace \beta_k \rbrace$ is the initialization---the fact that $\lbrace P_k \rbrace$ and $\lbrace M_k \rbrace$ are distinct is of little importance for our purposes as long as \ref{prop-sympd} to \ref{prop-condnum} are satisfied. Thus, we see that $\lbrace \beta_k \rbrace$ exhibit an analogue of the strong Markov property.

Now, to couple these two iterate sequences, let $\mathcal{G}_0 = \mathcal{F}_{\tau+1}$ and $\mathcal{G}_k = \sigma(\mathcal{F}_{\tau+1},Z_1,\ldots,Z_k)$, and, for $\delta >0$, define $\tau_\delta$ to be a stopping time with respect to $\lbrace \mathcal{G}_k \rbrace$ such that
\begin{equation}
\tau_\delta = \min\left\lbrace k \geq 0: \norm{ \dot{F}(\psi_k)}_2^2 \leq \delta \right\rbrace.
\end{equation} 
Then, on the event $\lbrace k \geq \tau_\delta \rbrace$, $\psi_{k+1} = \psi_k$. Moreover, on the event $\lbrace k < \tau_\delta \rbrace$,
\begin{equation}
\begin{aligned}
\psi_{k+1} &= \psi_{k} - P_k \dot{f}( \psi_k, Z_{k+1}) \\
&= \beta_{\tau+1+k} - M_{\tau+1 + k} \dot{f}( \beta_{\tau+1+k}, X_{\tau+2+k}) = \beta_{\tau+2+k}
\end{aligned}
\end{equation}
follows by induction. Therefore, for all $0 \leq k \leq \tau_\delta$, $\psi_k = \beta_{\tau+1+k}$; that is, the sequences are coupled in this interval. Owing to this coupling, we see that $\tau_\delta + 1$ is the number of iterates for $\beta_k$ to be within a ``$\delta$-region of zero gradient'' after iterate $\tau$. We now apply Zoutendijk's global convergence approach to conclude that $\tau_\delta$ is finite with probability one.

We now apply Zoutendijk's global convergence approach \cite{zoutendijk1970} to $\lbrace \psi_k \rbrace$ to conclude that $\Prb{ \tau_\delta < \infty} = 1$. First, by the fundamental theorem of calculus and \ref{condition-dg-lipschitz} (recall, with constant $C$),
\begin{align}
F(\psi_{k+1}) &\leq F(\psi_k) + \dot{F}(\psi_k)'(\psi_{k+1} - \psi_k) + \frac{C}{2}\norm{ \psi_{k+1} - \psi_k}_2^2 \\
			  & \begin{aligned}
			  &=F(\psi_k) - \dot{F}(\psi_k)'P_k \dot f (\psi_k, Z_{k+1}) \1{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta} \\
			  &+ \frac{C}{2} \norm{ P_k \dot f(\psi_k, Z_{k+1})}_2^2 \1{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta}. 
			  \end{aligned} \label{eqn-ftc}
\end{align}
We now take the conditional expectation of the resulting inequality with respect to $\mathcal{G}_k$. Note, since $\psi_k, P_k$ are measurable with respect to $ \mathcal{G}_k$ and $Z_{k+1}$ is independent of $\mathcal{G}_k$, then $\cond{ F(\psi_k)}{\mathcal G_k} = F(\psi_k)$ and 
\begin{equation}
\cond{ \dot{F}(\psi_k)'P_k \dot f(\psi_k, Z_{k+1})}{\mathcal{G}_k} = \dot{F}(\psi_k)'P_k \dot{F}(\psi_k).
\end{equation}
For the third term in (\ref{eqn-ftc}), we will need to make use of \ref{condition-noise-grad} (with parameters $C_1,C_2 \geq 0$).
\begin{align}
&\cond{ \norm{ P_k \left[ \dot f(\psi_k, Z_{k+1}) - \dot{F}(\psi_k) + \dot{F}(\psi_k) \right]}_2^2}{\mathcal G_k} \nonumber \\
&= \cond{ \norm{P_k \left[ \dot f(\psi_k,Z_{k+1}) - \dot{F}(\psi_k) \right]}_2^2}{\mathcal{G}_k} + \dot F(\psi_k)'P_k^2 \dot F(\psi_k) \\
&\leq C_1\lambda_{\max}(P_k)^2 + C_2 \lambda_{\max}(P_k)^2 \norm{ \dot{F}(\psi_k)}_2^2 + \dot F(\psi_k)'P_k^2 \dot F(\psi_k)
\end{align}
Putting the calculation for these three terms together in (\ref{eqn-ftc}), we conclude
\begin{equation} \label{eqn-ftc-cond}
\begin{aligned}
&\cond{F(\psi_{k+1})}{\mathcal{G}_k} \leq F(\psi_k) + \frac{CC_1}{2} \lambda_{\max}(P_k)^2 -  \1{ \norm{ \dot{F}(\psi_k)}_2^2 > \delta} \\
&\times \left[\dot{F}(\psi_k)'P_k \dot F(\psi_k) - \frac{C}{2} \dot{F}(\psi_k)'P_k^2 \dot F(\psi_k) - \frac{C C_2}{2} \lambda_{\max}(P_k)^2 \norm{ \dot F(\psi_k)}_2^2 \right]. 
\end{aligned}
\end{equation}
We can find an upper bound for (\ref{eqn-ftc-cond}) by finding a lower bound for the third term in the right hand side of the inequality. In particular, we will lower bound
\begin{equation} \label{eqn-ftc-cond-min}
