\begin{lemma} \label{lemma-pk-satisfy-mk-properties}
With probability one, $\lbrace P_k \rbrace$ satisfy \ref{prop-sympd} to \ref{prop-condnum}. Moreover, with probability one, for all $k \geq 0$ and any eigenvalue $\lambda$ of $P_k$,
\begin{equation}
\frac{1}{2}\lambda_{\min}(P_k) \leq \lambda - \frac{C}{2} \lambda^2 - \frac{C C_2}{2} \lambda_{\max}(P_k)^2.
\end{equation}
\end{lemma}

\begin{proof}
The result follows from a standard divide and conquer argument. For \ref{prop-sympd},
\begin{align}
&\Prb{ P_k = P_k', P_k \succ 0 } = \Prb{ M_{\tau+1+k}' = M_{\tau+1+k}, M_{\tau+1+k} \succ 0} \\
&= \sum_{j=0}^\infty \condPrb{ M_{j + 1 +k}' = M_{j + 1 +k}, M_{j+1+k} \succ 0}{\tau = j} \Prb{ \tau = j} \\
&= \sum_{j=0}^\infty \underbrace{\Prb{ M_{j + 1 +k}' = M_{j + 1 +k}, M_{j+1+k} \succ 0 }}_{=1~\text{by \ref{prop-sympd} on } \lbrace M_k \rbrace } \Prb{ \tau=j} \\
&= \sum_{j=0}^\infty \Prb{ \tau = j} \\
&= \Prb{ \tau < \infty } = 1.
\end{align}
Similarly, for \ref{prop-maxeig},
\begin{align}
&\Prb{ \sum_{k=0}^\infty \lambda_{\max}(P_k)^2 < S} \\
&= \sum_{j=0}^\infty \underbrace{\condPrb{ \sum_{k=0}^\infty \lambda_{\max}(M_{j+1+k})^2 < S}{\tau=j}}_{=1~\text{by \ref{prop-maxeig} on } \lbrace M_k \rbrace} \Prb{ \tau=j} \\
&= \Prb{ \tau < \infty} =1.
\end{align}
The analogous arguments will show that the remaining conclusions of the lemma hold.
\qed
\end{proof}

Similarly, for \ref{prop-maxeig},
\begin{align}
&\Prb{ \sum_{k=0}^\infty \lambda_{\max}(P_k)^2 < S} \\
&= \sum_{j=0}^\infty \underbrace{\condPrb{ \sum_{k=0}^\infty \lambda_{\max}(M_{j+1+k})^2 < S}{\tau=j}}_{=1~\text{by \ref{prop-maxeig} on } \lbrace M_k \rbrace} \Prb{ \tau=j} \\
&= \Prb{ \tau < \infty} =1.
\end{align}

The analogous arguments will show that the remaining conclusions of the lemma hold.
\qed
\end{proof}

In data-driven and simulation-based disciplines, the optimization problem
\begin{equation} \label{problem}
\min_{\theta} F(\theta)
\end{equation}

omenclature[A, 1]{$F$}{Objective function that maps $\mathbb{R}^p 	o \mathbb{R}$. Also referred to as ``Deterministic Objective.''}

omenclature[A, 2]{$\dot F$}{Gradient function of the deterministic objective that maps $\mathbb{R}^p 	o \mathbb{R}^p$. Also referred to as ``Deterministic Gradient.''}

omenclature[A, 3]{$f$}{A function that maps $\mathbb{R}^p 	imes \mathbb{R}^d 	o \mathbb{R}$. Used to construct the deterministic objective, and is referred to as the ``Stochastic Objective.''}

omenclature[A, 4]{$\dot f$}{Gradient function of the stochastic objective with respect to the first argument, and maps $\mathbb{R}^p 	imes \mathbb{R}^d 	o \mathbb{R}^p$. Also referred to as the ``Stochastic Gradient.''}

omenclature[A, 5]{$	heta$}{The parameter to be optimized in the objective function. Takes value in $\mathbb{R}^p$.}

omenclature[A, 6]{$
orm{\cdot}_2$}{If the argument is a vector, this refers to the Euclidean norm of the vector. If the argument is a matrix, this refers to the Operator 2-norm.}

omenclature[A, 7]{$\lambda_{\max}$}{The largest eigenvalue corresponding to a given symmetric, positive definite matrix argument.}

omenclature[A, 8]{$\lambda_{\min}$}{The smallest eigenvalue corresponding to the given symmetric, positive definite matrix argument.}

omenclature[A, 9]{$\kappa $}{The 2-norm condition number of the given matrix.}

\nomenclature[B, 1]{$\mathbb{P}$}{The probability operator with respect to the underlying Probability Space.}
\nomenclature[B, 2]{$\mathbb{E}$}{The expectation operator corresponding to the underlying Probability Space.}
\nomenclature[B, 3]{$X, X_k$}{Independent, identically distributed random variables that map from the underlying Probability Space to $\mathbb{R}^d$.}

\begin{definition}
A function that satisfies the BCN conditions is referred to as a BCN function.
\end{definition}

Let $\lbrace X_k : k \in \mathbb{N} \rbrace$ be independent and identically distributed random variables that have the same distribution as $X$. Let $\beta_0$ be either a fixed or random quantity in $\mathbb{R}^p$. Let $\mathcal{F}_0 = \sigma(\beta_0)$ and $\mathcal{F}_k = \sigma(\beta_0, X_1,\ldots,X_k)$ denote the corresponding elements of the usual filtration. Define the Stochastic Gradient Descent iterates $\lbrace \beta_k : k \in \mathbb{N} \rbrace$ recursively by
\begin{equation}
\beta_{k+1} = \beta_k - M_k \dot f (\beta_k, X_{k+1}),
\end{equation}

where $\lbrace M_k \rbrace$ are matrices that satisfy:
\condition{prop-sympd}{The matrices $\lbrace M_k \rbrace$ are symmetric and positive definite.}{P1}
\condition{prop-maxeig}{There exists an $S > 0$ such that
$$\sum_{k=0}^\infty \lambda_{\max}(M_k)^2 < S,$$
where $\lambda_{\max}(\cdot)$ denotes the largest eigenvalue of the given matrix.}{P2}
\condition{prop-mineig}{The sum,
$$\sum_{k=0}^\infty \lambda_{\min}(M_k),$$
diverges, where $\lambda_{\min}(\cdot)$ is the smallest eigenvalue of the given matrix.}{P3}
\condition{prop-condnum}{The condition numbers of $\lbrace M_k \rbrace$ with respect to operator 2-norm, $\lbrace \kappa(M_k) \rbrace$, satisfy
$$ \lim_{k \to \infty} \lambda_{\max}(M_k) \kappa(M_k) = 0.$$
}{P4}

\begin{remark}
We also note that all of the inequalities and equalities below hold with probability one, even if this is not explicitly stated.
\end{remark}
\begin{remark}
We also point out that the probabilities and expectations below should be conditional on $\mathcal{F}_0$. However, to avoid the additional cumbersome notation, we will not explicitly state this.
\end{remark}

Now, using $\tau$, we will define a sequence of iterates $\lbrace \psi_k \rbrace$ that we will eventually couple with $\lbrace \beta_k \rbrace$. To define $\lbrace \psi_k \rbrace$, let
\begin{enumerate}
\item $Z_k := X_{\tau+1+k}$ for all $k \in \mathbb{N}$.
\item $\psi_0 := \beta_{\tau + 1}$.
\item For all $k \in \lbrace 0 \rbrace \cup \mathbb{N}$, $P_k := M_{\tau+1+k}$ and
\begin{equation} \label{eqn-psi-iter}
\psi_{k+1} := \psi_k - P_k \dot f( \psi_k, Z_{k+1}) \1{ \norm{\dot F(\psi_k)}_2^2 > \delta},
\end{equation}
where $\1{ \cdot} $ is the indicator function for the given event.
\end{enumerate} 

There are two properties of these quantities that are worth noting: $\lbrace Z_k \rbrace$ are independent and identically distributed; $\lbrace P_k \rbrace$ inherit the properties of $\lbrace M_k \rbrace$ with probability one. The former is verified by Theorem 4.1.3 of \cite{durrett2010}, which states that $\lbrace Z_k \rbrace$ are mutually independent and independent of $\mathcal{F}_{\tau+1}$, and have the same distribution as $X_1$. The latter is verified by the following lemma.
